/// The child order of the complex type `symbol` declared in `namespace`, or `None` if the
/// tables do not cover it.
///
/// `namespace` may be either the Strict or the Transitional URI. This is the by-name
/// lookup a tree walk needs; a serializer holds its own type's `ChildOrder` as a constant
/// instead of calling this.
#[must_use]
pub fn find(namespace: &str, symbol: &str) -> Option<&'static ChildOrder> {
    let table: &'static [ChildOrder] = if in_namespace(namespace, DML_MAIN) {
        &DML_MAIN_TYPES
    } else if in_namespace(namespace, PML) {
        &PML_TYPES
    } else if in_namespace(namespace, DML_CHART) {
        &DML_CHART_TYPES
    } else {
        return None;
    };
    table
        .binary_search_by(|order| order.symbol.cmp(symbol))
        .ok()
        .map(|index| &table[index])
}

/// The child order of the complex type a schema's **global** element declaration names —
/// how a walk over a whole part starts, given only the part's root element name.
#[must_use]
pub fn root_element(namespace: &str, local: &str) -> Option<&'static ChildOrder> {
    let symbol = if in_namespace(namespace, DML_MAIN) {
        match local {
            "blip" => "CT_Blip",
            "graphic" => "CT_GraphicalObject",
            "tbl" => "CT_Table",
            "tblStyleLst" => "CT_TableStyleList",
            "theme" => "CT_OfficeStyleSheet",
            "themeManager" => "CT_EmptyElement",
            "themeOverride" => "CT_BaseStylesOverride",
            "videoFile" => "CT_VideoFile",
            _ => return None,
        }
    } else if in_namespace(namespace, PML) {
        match local {
            "cmAuthorLst" => "CT_CommentAuthorList",
            "cmLst" => "CT_CommentList",
            "handoutMaster" => "CT_HandoutMaster",
            "notes" => "CT_NotesSlide",
            "notesMaster" => "CT_NotesMaster",
            "oleObj" => "CT_OleObject",
            "presentation" => "CT_Presentation",
            "presentationPr" => "CT_PresentationProperties",
            "sld" => "CT_Slide",
            "sldLayout" => "CT_SlideLayout",
            "sldMaster" => "CT_SlideMaster",
            "sldSyncPr" => "CT_SlideSyncProperties",
            "tagLst" => "CT_TagList",
            "viewPr" => "CT_ViewProperties",
            _ => return None,
        }
    } else if in_namespace(namespace, DML_CHART) {
        match local {
            "chart" => "CT_RelId",
            "chartSpace" => "CT_ChartSpace",
            _ => return None,
        }
    } else {
        return None;
    };
    find(namespace, symbol)
}

